ALTER TABLE businesses ADD COLUMN IF NOT EXISTS category text default 'General';
ALTER TABLE businesses ADD COLUMN IF NOT EXISTS contact text default '';
ALTER TABLE businesses ADD COLUMN IF NOT EXISTS taxrate numeric default 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS sku text default '';
ALTER TABLE products ADD COLUMN IF NOT EXISTS category text default 'General';
ALTER TABLE products ADD COLUMN IF NOT EXISTS cost bigint default 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS minimum integer default 3;
CREATE TABLE IF NOT EXISTS customers(id serial primary key,bid integer not null references businesses(id),name text not null,email text not null,phone text not null,address text not null);
CREATE TABLE IF NOT EXISTS accounts(id serial primary key,bid integer not null references businesses(id),name text not null,type text not null,opening bigint not null);
CREATE TABLE IF NOT EXISTS docs(id serial primary key,bid integer not null references businesses(id),kind text not null,customer integer not null references customers(id),lines jsonb not null,subtotal bigint not null,tax bigint not null,total bigint not null,due date not null,status text not null,created timestamptz default now(),source integer unique references docs(id));
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS customer integer references customers(id);
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS account integer references accounts(id);
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS document integer references docs(id);
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS category text default 'General';
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS method text default 'Cash';
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS reversed boolean default false;
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS reconciled boolean default false;
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS taxable boolean default false;
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS taxrate numeric default 0;
ALTER TABLE ledger ADD COLUMN IF NOT EXISTS cogs bigint default 0;
CREATE TABLE IF NOT EXISTS lineitems(id serial primary key,entry integer not null references ledger(id),product integer not null references products(id),name text not null,qty integer not null,price bigint not null,cost bigint not null);
CREATE TABLE IF NOT EXISTS movements(id serial primary key,bid integer not null references businesses(id),product integer not null references products(id),qty integer not null,reason text not null,created timestamptz default now());
CREATE TABLE IF NOT EXISTS audit(id serial primary key,bid integer not null references businesses(id),uid integer not null references users(id),action text not null,created timestamptz default now());
CREATE INDEX IF NOT EXISTS ledger_business_date ON ledger(bid,created);
CREATE INDEX IF NOT EXISTS products_business ON products(bid);
CREATE UNIQUE INDEX IF NOT EXISTS product_skus ON products(bid,sku) WHERE sku<>'';
CREATE TABLE IF NOT EXISTS resets(token text primary key,uid integer not null references users(id),expires timestamptz not null);
